import re
import pytesseract
from PIL import Image, ImageOps, ImageFilter, ImageEnhance
from openpyxl import Workbook


MONTHS = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'SEPT': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
    'JANUARY': 1, 'FEBRUARY': 2, 'MARCH': 3, 'APRIL': 4, 'JUNE': 6,
    'JULY': 7, 'AUGUST': 8, 'SEPTEMBER': 9, 'OCTOBER': 10, 'NOVEMBER': 11, 'DECEMBER': 12,
}


KEYWORD_TIERS = [
    [r'GRAND\s*TOTAL'],
    [r'TOTAL\s*RM', r'TOTAL\s*:\s*RM'],
    [r'TOTAL\s*AMOUNT'],
    [r'NETT?\s*TOTAL', r'TOTAL\s*DUE', r'AMOUNT\s*DUE', r'BALANCE\s*DUE', r'TOTAL', r'AMOUNT'],
]

EXCLUSION_KEYWORDS = [
    r'SUB\s*TOTAL',
    r'TAX',
    r'GST',
    r'SST',
    r'DISCOUNT',
    r'CHANGE',
    r'CASH\s*TENDERED',
]


def multi_pass_ocr(image_path):
    """Run OCR with several preprocessing variants and return concatenated text."""
    img = Image.open(image_path)
    gray = ImageOps.grayscale(img)

    variants = [gray]
    variants.append(ImageOps.autocontrast(gray))
    variants.append(gray.filter(ImageFilter.SHARPEN))
    variants.append(ImageOps.autocontrast(gray).filter(ImageFilter.SHARPEN))
    for c in [1.5, 2.0, 2.5, 3.0]:
        v = ImageEnhance.Contrast(gray).enhance(c)
        v = v.filter(ImageFilter.SHARPEN)
        variants.append(v)
    scaled = ImageOps.autocontrast(gray).resize((gray.width * 2, gray.height * 2))
    variants.append(scaled)
    variants.append(scaled.filter(ImageFilter.SHARPEN))

    psm_modes = ['--psm 6', '--psm 4', '--psm 11']
    all_text = []
    for v in variants:
        for psm in psm_modes:
            try:
                t = pytesseract.image_to_string(v, config=psm)
                if t.strip():
                    all_text.append(t)
            except Exception:
                pass
    return '\n'.join(all_text)


def _normalize_date(day, month, year):
    try:
        day = int(day)
        month = int(month)
        year = int(year)
        if year < 100:
            year += 2000
        if year < 2000 or year > 2099:
            return None
        if not (1 <= month <= 12 and 1 <= day <= 31):
            return None
        return f'{year:04d}-{month:02d}-{day:02d}'
    except (ValueError, TypeError):
        return None


def extract_date(text):
    """Find the first date mentioned in the OCR text."""
    patterns = [
        r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})\b',
        r'\b(\d{1,2})\s+([A-Za-z]+)[,\s]+(\d{4})\b',
    ]
    for raw_line in text.split('\n'):
        line = raw_line.strip()
        for pat in patterns:
            m = re.search(pat, line)
            if not m:
                continue
            g = m.groups()
            if g[1].isalpha():
                month_name = g[1].upper()
                if month_name in MONTHS:
                    d = _normalize_date(g[0], MONTHS[month_name], g[2])
                    if d:
                        return d
            else:
                d = _normalize_date(g[0], g[1], g[2])
                if d:
                    return d
    return None


_NUM_RE = re.compile(r'\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2}')


def _last_number(line):
    nums = _NUM_RE.findall(line)
    if not nums:
        return None
    return nums[-1].replace(',', '')


def _is_excluded(line):
    up = line.upper()
    for ex in EXCLUSION_KEYWORDS:
        if re.search(ex, up):
            return True
    return False


def extract_total(text):
    """Extract total amount using keyword priority tiers."""
    lines = text.split('\n')

    for tier in KEYWORD_TIERS:
        tier_pat = re.compile('|'.join(tier))
        for idx, raw_line in enumerate(lines):
            line = raw_line.strip()
            up = line.upper()
            if not tier_pat.search(up):
                continue
            if _is_excluded(line):
                continue
            num = _last_number(line)
            if num:
                return num
            # Fallback: look at next non-empty line
            for j in range(idx + 1, min(idx + 3, len(lines))):
                next_line = lines[j].strip()
                if not next_line:
                    continue
                num = _last_number(next_line)
                if num:
                    return num
                break
    return None


def process_image(path):
    text = multi_pass_ocr(path)
    date = extract_date(text)
    total = extract_total(text)
    return date, total


def main():
    img_dir = '/app/workspace/dataset/img'
    files = sorted(f for f in os.listdir(img_dir) if f.lower().endswith('.jpg'))

    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])

    for f in files:
        path = os.path.join(img_dir, f)
        date, total = process_image(path)
        print(f'{f}: date={date}, total={total}')
        ws.append([f, date, total])

    wb.save('/app/workspace/stat_ocr.xlsx')


if __name__ == '__main__':
    main()
